        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 2000000,
                    activePlayers: 50000,
                    studioReputation: 70,
                    talentMorale: 75,
                    metacriticAvg: 72,
                    totalRevenue: 0,
                    totalCosts: 0,
                    revenueHistory: [],
                    profitHistory: [],
                    playerHistory: [],
                    reputationHistory: [],
                    moraleHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    devBudget: 250,
                    monetization: 'premium',
                    liveOpsSpend: 100,
                    marketingSpend: 150,
                    esportsInvest: 50,
                    crunchPolicy: 'none'
                };
            }
            this._updateBriefing(state);
        }
        validateDecisions(decisions) {
            var devInput = document.getElementById('devBudgetInput');
            if (devInput) decisions.devBudget = parseInt(devInput.value);
            var monSelect = document.getElementById('monetizationSelect');
            if (monSelect) decisions.monetization = monSelect.value;
            var liveOpsInput = document.getElementById('liveOpsInput');
            if (liveOpsInput) decisions.liveOpsSpend = parseInt(liveOpsInput.value);
            var marketingInput = document.getElementById('marketingInput');
            if (marketingInput) decisions.marketingSpend = parseInt(marketingInput.value);
            var esportsInput = document.getElementById('esportsInput');
            if (esportsInput) decisions.esportsInvest = parseInt(esportsInput.value);
            var crunchSelect = document.getElementById('crunchSelect');
            if (crunchSelect) decisions.crunchPolicy = crunchSelect.value;
            if (!decisions.devBudget || decisions.devBudget < 100 || decisions.devBudget > 500) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('dev_budget_warning'), 'warning');
                return false;
            }
            if (!decisions.liveOpsSpend && decisions.liveOpsSpend !== 0 || decisions.liveOpsSpend < 0 || decisions.liveOpsSpend > 300) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('live_ops_warning'), 'warning');
                return false;
            }
            if (!decisions.marketingSpend || decisions.marketingSpend < 50 || decisions.marketingSpend > 400) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('marketing_warning'), 'warning');
                return false;
            }
            if (!decisions.esportsInvest && decisions.esportsInvest !== 0 || decisions.esportsInvest < 0 || decisions.esportsInvest > 200) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('esports_warning'), 'warning');
                return false;
            }
            this._updateBriefing(window.mySimulation.state);
            return true;
        }
        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var quarter = state.currentPeriod;
            var totalSpend = (d.devBudget + d.liveOpsSpend + d.marketingSpend + d.esportsInvest) * 1000;
            var crunchQualityBonus = 0;
            var moralePenalty = 0;
            if (d.crunchPolicy === 'moderate') {
                crunchQualityBonus = 5;
                moralePenalty = 10;
            } else if (d.crunchPolicy === 'heavy') {
                crunchQualityBonus = 12;
                moralePenalty = 25;
            } else {
                moralePenalty = -5;
            }
            var devQuality = Math.min(100, 40 + (d.devBudget / 500) * 35 + (ds.talentMorale / 100) * 15 + crunchQualityBonus);
            var randomFactor = 0.85 + Math.random() * 0.3;
            devQuality = Math.round(devQuality * randomFactor);
            devQuality = Math.max(30, Math.min(100, devQuality));
            var baseArpdau = 0;
            var playerMultiplier = 1;
            // --- v1.1.0 monetization rebalance ---
            // Previously premium (ARPDAU 0, playerMult 0.7) had zero recurring revenue and
            // a collapsing player base, so it lost money under ALL play — a dominated trap.
            // Hybrid (0.08 / 1.1) was strictly dominated by f2p (lower ARPU AND lower growth),
            // so it also could not win. Now all three models are viable and distinct:
            //   premium = small, loyal base + high per-buyer value (quality-gated upfront + DLC)
            //   hybrid  = mid audience, high ARPU (base price + battle pass)
            //   f2p     = largest audience, low ARPU (unchanged)
            if (d.monetization === 'premium') {
                baseArpdau = 0.07;        // recurring DLC/expansion revenue (was 0.0)
                playerMultiplier = 1.05;  // stable loyal base (was 0.7, which collapsed)
            } else if (d.monetization === 'f2p') {
                baseArpdau = 0.12;
                playerMultiplier = 1.5;
            } else {
                baseArpdau = 0.16;        // battle pass + base price ARPU (was 0.08)
                playerMultiplier = 1.25;  // (was 1.1)
            }
            var marketingEffect = (d.marketingSpend / 400) * 0.4 + 0.6;
            var liveOpsRetention = 0.7 + (d.liveOpsSpend / 300) * 0.25;
            var esportsGrowth = (d.esportsInvest / 200) * 0.15;
            var q2DauPenalty = (quarter === 2) ? 0.92 : 1.0;
            var newPlayers = Math.round(ds.activePlayers * playerMultiplier * marketingEffect * q2DauPenalty);
            var retainedPlayers = Math.round(newPlayers * liveOpsRetention);
            var playerGrowthFromEsports = Math.round(retainedPlayers * esportsGrowth);
            var totalPlayers = retainedPlayers + playerGrowthFromEsports;
            var premiumSalesRevenue = 0;
            if (d.monetization === 'premium') {
                var newBuyers = Math.round(totalPlayers * 0.33 * (devQuality / 100));
                premiumSalesRevenue = newBuyers * 60;
            }
            var liveServiceRevenue = Math.round(totalPlayers * baseArpdau * 90);
            var totalRevenue = premiumSalesRevenue + liveServiceRevenue;
            if (quarter === 3) {
                var launchBonus = Math.round(d.devBudget * 1000 * (devQuality / 100) * 1.5);
                totalRevenue += launchBonus;
            }
            var quarterProfit = totalRevenue - totalSpend;
            ds.cash += quarterProfit;
            ds.activePlayers = totalPlayers;
            ds.totalRevenue += totalRevenue;
            ds.totalCosts += totalSpend;
            ds.talentMorale = Math.max(10, Math.min(100, ds.talentMorale - moralePenalty));
            var reputationChange = 0;
            reputationChange += (devQuality - 70) * 0.2;
            reputationChange += (d.esportsInvest / 200) * 5;
            if (d.crunchPolicy === 'heavy') {
                reputationChange -= 5;
            }
            if (d.liveOpsSpend > 150) {
                reputationChange += 3;
            }
            ds.studioReputation = Math.max(0, Math.min(100, Math.round(ds.studioReputation + reputationChange)));
            ds.metacriticAvg = Math.round((ds.metacriticAvg * (quarter - 1) + devQuality) / quarter);
            ds.revenueHistory.push(totalRevenue);
            ds.profitHistory.push(quarterProfit);
            ds.playerHistory.push(totalPlayers);
            ds.reputationHistory.push(ds.studioReputation);
            ds.moraleHistory.push(ds.talentMorale);
            var self = this;
            setTimeout(function() {
                self._updateBriefing({
                    currentPeriod: state.currentPeriod + 1
                });
            }, 500);
            return {
                period: state.currentPeriod,
                devQuality: devQuality,
                totalRevenue: totalRevenue,
                totalSpend: totalSpend,
                quarterProfit: quarterProfit,
                activePlayers: totalPlayers,
                reputation: ds.studioReputation,
                morale: ds.talentMorale,
                metacritic: ds.metacriticAvg,
                cash: ds.cash
            };
        }
