        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalRev = 0;
            var totalProfit = 0;
            var avgMetacritic = 0;
            var finalPlayers = 0;
            var finalReputation = 0;
            var finalMorale = 0;
            for (var i = 0; i < history.length; i++) {
                var r = history[i].results || {};
                totalRev += r.totalRevenue || 0;
                totalProfit += r.quarterProfit || 0;
            }
            var last = history[history.length - 1].results || {};
            finalPlayers = last.activePlayers || 0;
            finalReputation = last.reputation || 0;
            finalMorale = last.morale || 0;
            avgMetacritic = last.metacritic || 0;
            var score = 0;
            score += Math.min(30, (totalProfit / 1000000) * 15);
            score += Math.min(25, (finalReputation / 100) * 25);
            score += Math.min(20, (avgMetacritic / 100) * 20);
            score += Math.min(15, (finalPlayers / 80000) * 15);
            score += Math.min(10, (finalMorale / 100) * 10);
            score = Math.round(score);
            var performance = 'Needs Improvement';
            if (score >= 70) performance = 'Excellent';
            else if (score >= 50) performance = 'Good';
            else if (score >= 30) performance = 'Fair';
            var insights = [];
            if (totalProfit > 500000) {
                insights.push('Strong financial management — your studio is profitable and sustainable.');
            } else if (totalProfit < 0) {
                insights.push('The studio lost money overall. Review the balance between spending and revenue generation.');
            }
            if (finalReputation >= 80) {
                insights.push('Outstanding studio reputation — you built a brand players trust.');
            } else if (finalReputation < 50) {
                insights.push('Studio reputation suffered. Community and quality investments pay long-term dividends.');
            }
            if (finalMorale < 40) {
                insights.push('Talent morale is critically low. Crunch culture has a real cost in retention and quality.');
            } else if (finalMorale >= 80) {
                insights.push('Your team is motivated and engaged — a key competitive advantage.');
            }
            if (avgMetacritic >= 80) {
                insights.push('Excellent game quality. High review scores drive organic growth and player loyalty.');
            }
            if (insights.length === 0) {
                insights.push('A balanced approach. Consider how different trade-offs affect long-term studio health.');
            }
            return {
                totalRevenue: totalRev,
                totalProfit: totalProfit,
                finalPlayers: finalPlayers,
                studioReputation: finalReputation,
                metacriticAvg: avgMetacritic,
                talentMorale: finalMorale,
                score: score,
                performance: performance,
                insights: insights
            };
        }
